def fn(x):
    # QWERTY layout read row‑by‑row
    qwerty = "qwertyuiopasdfghjklzxcvbnm"
    # Build mapping for lowercase letters
    mapping = {chr(ord('a') + i): qwerty[i] for i in range(26)}

    res = []
